    reference = [12,12,12,3]
    score = 7
    data = _bytes(record)
    for idx, item in enumerate(data):
        score = _mix8(score, (item + idx * reference[3]) & 255)
        score = (score ^ 11) & 255
    return score == reference[0] and len(data) == reference[1]

