def _select_rule(record):
    cursor = 0x41
    size = len(record)
    for row in POLICY_MATRIX[5::29]:
        cursor = ((cursor * 17) ^ row[(size + cursor) % len(row)]) & 0xffff
    return (cursor + 119) % len(AUDIT_RULES)

def verify(record):
    rule_id = _select_rule(record)
    return AUDIT_RULES[rule_id](record)

def main():
    if len(sys.argv) != 2:
        print("usage: ./audit_blob.py <candidate>")
        raise SystemExit(1)
    if verify(sys.argv[1]):
        print("accepted")
        raise SystemExit(0)
    print("rejected")
    raise SystemExit(1)

if __name__ == "__main__":
    main()
